/**
 * Files an ordinary issue for the latest started occurrence of every recurring rule.
 *
 * Must call (do not reimplement): createIssue, can
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const DAY_MS = 86_400_000;

function parseDay(day: string): number {
  const [y, m, d] = day.split("-").map(Number);
  return Date.UTC(y!, m! - 1, d!);
}

function formatDay(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

/** The calendar day `now` falls on in `timeZone`, as `YYYY-MM-DD`. */
function localDay(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    calendar: "iso8601",
    numberingSystem: "latn",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
  return `${get("year").padStart(4, "0")}-${get("month")}-${get("day")}`;
}

/** The latest occurrence of `rule` that has started by `now`, or null. */
export function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localDay(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  let ms = parseDay(today);
  for (let i = 0; i < 7; i += 1, ms -= DAY_MS) {
    const weekday = new Date(ms).getUTCDay() === 0 ? 7 : new Date(ms).getUTCDay();
    if (weekday !== rule.weekday) continue;
    const day = formatDay(ms);
    return day >= rule.startsOn ? day : null;
  }
  return null;
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if (await fileOccurrence(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** True when an issue was created. */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
  const latest = latestOccurrence(rule, now);
  if (latest === null) return false;
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) return false;

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: rule.createdBy, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setPaused(rule.orgId, rule.id, true);
    return false;
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (assignee === null || assignee.status !== "active") assigneeId = null;
  }

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${latest})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    logger.warn("recurring issue refused; will retry", {
      recurringIssueId: rule.id,
      reason: error instanceof Error ? error.message : String(error),
    });
    return false;
  }

  await recurringRepo.setLastOccurrence(rule.orgId, rule.id, latest);
  return true;
}
